contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseToken,
        address nft,
        uint128 virtBase,
        uint128 virtNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        require(feeRate <= 5_000);

        bool reverted1;
        try c.initialize(baseToken, nft, virtBase, virtNft, changeFee, feeRate, merkleRoot, useOracle, payRoy) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        bool reverted2;
        try c.initialize(baseToken, nft, virtBase, virtNft, changeFee, feeRate, merkleRoot, useOracle, payRoy) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        bool ok = !reverted1 && reverted2
            && c.initialized()
            && c.baseToken() == baseToken
            && c.nft() == nft
            && c.virtualBaseTokenReserves() == virtBase
            && c.virtualNftReserves() == virtNft
            && c.changeFee() == changeFee
            && c.feeRate() == feeRate
            && c.merkleRoot() == merkleRoot
            && c.useStolenNftOracle() == useOracle
            && c.payRoyalties() == payRoy;

        assert(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 virtBase,
        uint128 virtNft,
        uint16 feeRate,
        uint256 outputAmount
    ) public {
        require(feeRate <= 5_000);
        require(virtNft > 1 && outputAmount < virtNft);
        // bound products to avoid overflow
        require(uint256(virtBase) <= (type(uint256).max - type(uint256).max / 10**18) / 10**18);
        require(outputAmount <= uint256(virtBase) && uint256(virtBase) <= (type(uint256).max - (virtNft - 1)) / outputAmount == false ? uint256(virtBase) <= type(uint256).max / outputAmount : true);
        require(uint256(virtBase) <= type(uint256).max / (outputAmount > 0 ? outputAmount : 1));
        require(feeRate <= 5_000 && c2_unused());

        c.initialize(address(0), address(0), virtBase, virtNft, 0, feeRate, bytes32(0), false, false);

        (uint256 netInput, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 denom = uint256(virtNft) - outputAmount;
        uint256 gross = (uint256(outputAmount) * uint256(virtBase) + denom - 1) / denom;
        uint16 protoRate = Factory(c.factory()).protocolFeeRate();

        assert(
            netInput == gross + feeAmount + protocolFeeAmount &&
            feeAmount == gross * feeRate / 10_000 &&
            protocolFeeAmount == gross * protoRate / 10_000
        );
    }

    function c2_unused() internal pure returns (bool) { return true; }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 virtBase,
        uint128 virtNft,
        uint16 feeRate,
        uint256 inputAmount
    ) public {
        require(virtNft > 0);
        require(feeRate <= 5_000);
        require(inputAmount <= type(uint128).max);
        require(uint256(virtBase) <= type(uint256).max / (uint256(virtNft) + inputAmount));
        require(uint256(virtBase) <= type(uint256).max / inputAmount || inputAmount == 0);
        require(uint256(virtBase) <= (type(uint256).max) / 10_000 / 10_000 + 10**30 || inputAmount == 0);
        require(inputAmount <= (type(uint256).max - uint256(virtBase) * 10_000 * 10_000) / (uint256(virtNft) + inputAmount) || uint256(virtBase) * (uint256(virtNft) + inputAmount) <= type(uint256).max);

        c.initialize(address(0), address(0), virtBase, virtNft, 0, feeRate, bytes32(0), false, false);

        (uint256 netOutput, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);

        uint256 output = uint256(inputAmount) * uint256(virtBase) / (uint256(virtNft) + inputAmount);
        uint16 protoRate = Factory(c.factory()).protocolFeeRate();

        assert(
            netOutput == output - feeAmount - protocolFeeAmount &&
            feeAmount == output * feeRate / 10_000 &&
            protocolFeeAmount == output * protoRate / 10_000
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint16 initialFeeRate, uint16 badFeeRate, uint16 goodFeeRate) public {
        require(initialFeeRate <= 5_000);
        require(badFeeRate > 5_000);
        require(goodFeeRate <= 5_000);

        c.initialize(address(0), address(0), 1, 1, 0, initialFeeRate, bytes32(0), false, false);

        bool reverted1;
        try c.setFeeRate(badFeeRate) { reverted1 = false; } catch { reverted1 = true; }

        uint16 afterBad = c.feeRate();

        c.setFeeRate(goodFeeRate);

        uint16 afterGood = c.feeRate();

        assert(reverted1 && afterBad == initialFeeRate && afterGood == goodFeeRate);
    }

    receive() external payable {}
}

